#!/usr/bin/env php
<?php

declare(strict_types=1);

/**
 * Regenerate the golden-file baseline for the allocation engine.
 *
 * Run this only when a change to the engine's output is *intended* — a weight
 * retune, a reordering of the seeding heuristic, a revised tie-break. The pull
 * request must then record the accuracy and penalty before and after, because
 * a lower penalty bought with a lower placement rate is a trade, not an
 * improvement (docs/ALLOCATION_ENGINE.md §10).
 *
 * The baseline is generated by running the engine, not by hand, so it can only
 * ever be as good as the current code. Read the diff before committing it.
 *
 * Usage:
 *   php bin/regenerate-golden.php            # regenerate
 *   php bin/regenerate-golden.php --show     # print without writing
 */


namespace App\Bin;

use App\Domain\Allocation\AllocationEngine;
use App\Domain\Allocation\CandidateGenerator;
use App\Domain\Allocation\ConstraintChecker;
use App\Domain\Allocation\CostFunction;
use App\Domain\Allocation\CostWeights;
use App\Domain\Allocation\EngineOptions;
use App\Domain\Allocation\FixedClock;
use App\Domain\Allocation\Rng;
use Tests\Unit\Allocation\Fixture\ProblemBuilder;

if (\PHP_SAPI !== 'cli') {
    fwrite(STDERR, "This script must be run from the command line.\n");
    exit(1);
}

$root = \dirname(__DIR__);

if (! is_file($root . '/vendor/autoload.php')) {
    fwrite(STDERR, "Dependencies are not installed. Run: composer install\n");
    exit(1);
}

require $root . '/vendor/autoload.php';

// The reference dataset lives with the tests, so this script needs the dev
// autoloader. A production install will not have it, and that is correct: the
// baseline is a development artefact, never a runtime dependency.
if (! class_exists(ProblemBuilder::class)) {
    fwrite(STDERR, "The dev autoloader is missing. Run: composer install (without --no-dev)\n");
    exit(1);
}

/**
 * The reference dataset. Must stay byte-identical to
 * GoldenFileTest::referenceProblem() — a change here invalidates every stored
 * baseline, which is exactly the point of keeping it small and fixed.
 */
$builder = (new ProblemBuilder())
    ->standardWeek(3)
    ->room(20, features: ['projector'], shared: true, building: 'Main')
    ->room(40, features: ['projector'], shared: true, building: 'Main')
    ->room(60, features: [], shared: true, building: 'Annex')
    ->room(100, features: ['projector', 'lab_bench'], shared: true, building: 'Annex')
    ->session(1, 1, enrolledCount: 18, requiredFeatures: ['projector'], preferredBuilding: 'Main')
    ->session(1, 2, enrolledCount: 18, requiredFeatures: ['projector'], preferredBuilding: 'Main')
    ->session(2, 1, enrolledCount: 35, sequence: 1)
    ->session(2, 3, enrolledCount: 35, sequence: 2)
    ->session(3, 2, enrolledCount: 55, requiredFeatures: ['lab_bench'], preferredBuilding: 'Annex')
    ->session(3, 3, enrolledCount: 55, requiredFeatures: ['lab_bench'], preferredBuilding: 'Annex')
    ->lecturerUnavailableDay(3, 3);

$weights = CostWeights::balanced();
$checker = new ConstraintChecker();

$engine = new AllocationEngine(
    $checker,
    new CandidateGenerator($checker),
    new CostFunction($weights),
    new Rng(20260801),
);

$result = $engine->solve(
    $builder->build(),
    [],
    new EngineOptions(
        maxIterations: 250,
        stallLimit: 60,
        maxNeighbours: 40,
        randomSeed: 20260801,
        timeBudgetSeconds: 3600.0,
        clock: new FixedClock(0.0),
    ),
);

$payload = $result->toArray();

// duration_ms is wall-clock and would make the baseline machine-dependent.
unset($payload['metrics']['duration_ms']);

$json = json_encode($payload, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES) . "\n";
$target = $root . '/tests/Unit/Allocation/Fixture/golden/reference-run.json';

if (in_array('--show', $argv, true)) {
    fwrite(STDOUT, $json);
    exit(0);
}

if (! is_dir(\dirname($target))) {
    mkdir(\dirname($target), 0o775, true);
}

file_put_contents($target, $json);

fwrite(STDOUT, sprintf(
    "Wrote %s\n\n  sessions    %d\n  allocated   %d\n  unallocated %d\n"
    . "  accuracy    %.4f  (NFR-PERF-04 requires >= 0.9000)\n  penalty     %.4f\n\n"
    . "Review the diff, then commit it. An unallocated session in the baseline means\n"
    . "the reference dataset is no longer fully solvable — investigate before\n"
    . "accepting, because the reference dataset is chosen to have a clean solution.\n",
    $target,
    $result->metrics['total_sessions'],
    $result->metrics['assigned_sessions'],
    $result->metrics['unallocated_sessions'],
    $result->metrics['accuracy'],
    $result->metrics['total_penalty'],
));

if ($result->metrics['accuracy'] < 0.90) {
    fwrite(STDERR, "\nWARNING: accuracy is below the acceptance gate. The suite will fail.\n");
    exit(1);
}
